def _extend_children(children, item, get_handler):
    # Try keys-based access first (dict-like objects)
    keys_handler = get_handler('keys', item, raise_exc=False)
    if keys_handler:
        try:
            keys = keys_handler(item)
            get = get_handler('get', item, raise_exc=False)
            if get:
                for key in keys:
                    try:
                        children.append(get(item, key))
                    except Exception:
                        pass
            return
        except Exception:
            pass

    # Try iteration (list-like objects)
    iterate_handler = get_handler('iterate', item, raise_exc=False)
    if iterate_handler:
        try:
            for child in iterate_handler(item):
                children.append(child)
